CREATE TABLE recovery_secrets(user_id BIGINT PRIMARY KEY REFERENCES app_users(id), code_hash VARCHAR(64) NOT NULL, used_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vehicle_receipts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code VARCHAR(100) NOT NULL UNIQUE,source VARCHAR(500) NOT NULL,note VARCHAR(500),created_by BIGINT NOT NULL REFERENCES app_users(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted BOOLEAN DEFAULT FALSE NOT NULL);
ALTER TABLE vehicles ADD receipt_id BIGINT REFERENCES vehicle_receipts(id);
